import json, hashlib, itertools, re
from pathlib import Path

ROOT=Path(__file__).resolve().parent
OUT=ROOT/'phaseMicro3a-adaptive-depth-backfill-v1_questions.json'
questions=[]
seq={'ELAS':0,'CPS':0,'ITP':0}
source_id=6900000

def norm(s): return re.sub(r'\s+',' ',str(s).strip()).lower()
def ahash(answer): return hashlib.sha256(norm(answer).encode()).hexdigest()
def shash(obj): return hashlib.sha256(json.dumps(obj,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()

def add(fam,pool,subtopic,objective,skill,q,options,correct,feedback,typ='application',common='misapplies_concept',secondary=None):
    global source_id
    assert pool in ('easy','medium','hard')
    assert correct in options and len(options)==4 and len(set(options))==4
    seq[fam]+=1; source_id+=1
    rotation=(seq[fam]-1)%4
    options=list(options[rotation:]+options[:rotation])
    prefix={'ELAS':'PMA-ELAS','CPS':'PMA-CPS','ITP':'PMA-ITP'}[fam]
    pid={'ELAS':'elasticity','CPS':'consumer-and-producer-surplus','ITP':'international-trade-and-trade-policy'}[fam]
    tag={'ELAS':'elasticity','CPS':'consumer_producer_surplus','ITP':'international_trade_and_trade_policy'}[fam]
    cluster={'ELAS':'elasticity','CPS':'micro_consumer_producer_surplus','ITP':'micro_international_trade'}[fam]
    rec={
      'id':f"{prefix}-{pool[0].upper()}-{seq[fam]:03d}",
      'q':q,'options':options,'tag':tag,'type':typ,'objective':objective,'difficulty':pool,
      'conceptCluster':cluster,'primarySkill':skill,'secondarySkills':secondary or [],'repairSkill':skill,
      'commonError':common,'feedback':feedback,'aHash':ahash(correct),
      'sourceGame':'micro-concept-library','sourceChapter':[pid],'sourcePool':pool,
      'primaryConceptId':pid,'secondaryConceptIds':[],'instructionalRole':'main',
      'canonicalDifficulty':pool,'originalSourcePool':pool,'originalBossTier':None,
      'familyConceptId':pid,'subtopicIds':[subtopic],
    }
    rec['canonicalId']=rec['id']; rec['sourceId']=source_id
    rec['sourceHash']=shash({k:v for k,v in rec.items() if k not in ('sourceHash','sourceOccurrences')})
    rec['sourceOccurrences']=[{'sourceGame':'micro-concept-library','sourceFile':OUT.name,'sourceGlobal':'questions','sourcePool':pool,'routeKey':skill,'sourceRecordOrder':len(questions),'sourceId':source_id,'sourceHash':rec['sourceHash']}]
    questions.append(rec)

